/**
 * GU47 WP-21 BZ-10: bunker wear decals. Each floor gets 12 seeded floor decals (8 soot scorches, 4 concrete cracks)
 * from one shared pool of decal nodes that is moved to the active floor (all floors share the origin and only one is
 * drawn, so per-floor copies would leak), and gunfire leaves bullet holes on the wall it hits for 20 s (a ring of 12).
 * 24 decal nodes in all, inside the engine's 32-decal forward budget (`decals.telemetry().overBudget` stays false), one
 * draw each while visible. The three RGBA textures are generated by `scripts/make-decals.ts` from the pattern functions
 * here (own procedural art, no third-party source). Presentation only: placement reads the floor grid (PRD D8).
 */
import { CELL, isSolid, type FloorDef } from "../maps";

export const BZ_DECAL_TEXTURE_SIZE = 128;
export const BZ_DECAL_FILES = { scorch: "bz-scorch.png", crack: "bz-crack.png", bullet: "bz-bullet-hole.png" } as const;
export type DecalKind = keyof typeof BZ_DECAL_FILES;
export const decalUrl = (kind: DecalKind): string => `/aura-assets/decals/${BZ_DECAL_FILES[kind]}`;

/** Pool sizes: floor decals per floor (scorches first, then cracks) and the bullet-hole ring; Low tier uses half. */
export const BZ_FLOOR_DECALS = { scorch: 8, crack: 4 } as const;
export const BZ_FLOOR_DECAL_COUNT = BZ_FLOOR_DECALS.scorch + BZ_FLOOR_DECALS.crack;
export const BZ_BULLET_HOLES = 12;
export const BZ_BULLET_HOLE_SECONDS = 20;
export const BZ_DECAL_NODES = BZ_FLOOR_DECAL_COUNT + BZ_BULLET_HOLES;
export const decalsForTier = (tier: string): { floor: number; holes: number } =>
  (tier === "low" ? { floor: BZ_FLOOR_DECAL_COUNT / 2, holes: BZ_BULLET_HOLES / 2 } : { floor: BZ_FLOOR_DECAL_COUNT, holes: BZ_BULLET_HOLES });

export const floorDecalId = (i: number): string => `bz-floor-decal-${i}`;
export const bulletHoleId = (i: number): string => `bz-bullet-hole-${i}`;
export const floorDecalKind = (i: number): DecalKind => (i < BZ_FLOOR_DECALS.scorch ? "scorch" : "crack");

/** Deterministic [0, 1) hash of integers (cosmetic only). */
export function hash01(a: number, b: number, c = 0): number {
  let h = (Math.imul(a | 0, 0x27d4eb2d) ^ Math.imul(b | 0, 0x165667b1) ^ Math.imul(c | 0, 0x9e3779b1)) >>> 0;
  h = Math.imul(h ^ (h >>> 15), 0x85ebca6b) >>> 0;
  h = Math.imul(h ^ (h >>> 13), 0xc2b2ae35) >>> 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

export interface FloorDecalPose { readonly kind: DecalKind; readonly position: [number, number, number]; readonly yaw: number; readonly size: number }

/** Cells a floor decal may sit on: plain floor or a spawn, never water/grate (`,`), doors, the exit or a pickup. */
const DECAL_CELLS = new Set([".", "S"]);

/** The 12 seeded floor decals of a floor (same list every run; distinct cells). */
export function floorDecals(def: FloorDef): FloorDecalPose[] {
  const open: [number, number][] = [];
  def.rows.forEach((r, z) => { for (let x = 0; x < r.length; x++) if (DECAL_CELLS.has(r[x]!)) open.push([x, z]); });
  const picked = open
    .map((c, i) => ({ c, k: hash01(c[0], c[1], def.id + 101 + i * 0) }))
    .sort((a, b) => a.k - b.k)
    .slice(0, BZ_FLOOR_DECAL_COUNT);
  return picked.map(({ c }, i) => {
    const kind = floorDecalKind(i);
    const jx = (hash01(c[0], c[1], def.id + 7) - 0.5) * CELL * 0.4, jz = (hash01(c[1], c[0], def.id + 9) - 0.5) * CELL * 0.4;
    const size = kind === "scorch" ? 1.4 + hash01(c[0], c[1], 3) * 1.2 : 1.1 + hash01(c[0], c[1], 5) * 0.8;
    // 2 mm stack per index so overlapping decals never share a plane
    return { kind, position: [(c[0] + 0.5) * CELL + jx, 0.012 + i * 0.002, (c[1] + 0.5) * CELL + jz], yaw: hash01(c[0], c[1], 11) * Math.PI * 2, size };
  });
}

export interface WallHolePose { readonly position: [number, number, number]; readonly rotation: [number, number, number]; readonly normal: [number, number, number] }

/**
 * The wall face a player shot hit, or null when it hit an enemy or a prop in the open: the shot point sits in a solid
 * cell, or within `reach` of a solid neighbour, and the hole goes on that cell face, facing the open side.
 */
export function bulletHolePose(grid: ArrayLike<string>, w: number, h: number, x: number, z: number, y = 1.18, reach = 0.4): WallHolePose | null {
  const solid = (cx: number, cz: number) => cx < 0 || cz < 0 || cx >= w || cz >= h || isSolid(grid[cz * w + cx] ?? "#");
  const cx = Math.floor(x / CELL), cz = Math.floor(z / CELL);
  const faces: { n: [number, number]; d: number; open: boolean; cell: [number, number] }[] = [];
  if (solid(cx, cz)) {
    // inside a wall cell: nearest face toward an open neighbour
    const fx = x - cx * CELL, fz = z - cz * CELL;
    faces.push({ n: [-1, 0], d: fx, open: !solid(cx - 1, cz), cell: [cx, cz] }, { n: [1, 0], d: CELL - fx, open: !solid(cx + 1, cz), cell: [cx, cz] });
    faces.push({ n: [0, -1], d: fz, open: !solid(cx, cz - 1), cell: [cx, cz] }, { n: [0, 1], d: CELL - fz, open: !solid(cx, cz + 1), cell: [cx, cz] });
  } else {
    const fx = x - cx * CELL, fz = z - cz * CELL;
    faces.push({ n: [1, 0], d: fx, open: solid(cx - 1, cz), cell: [cx - 1, cz] }, { n: [-1, 0], d: CELL - fx, open: solid(cx + 1, cz), cell: [cx + 1, cz] });
    faces.push({ n: [0, 1], d: fz, open: solid(cx, cz - 1), cell: [cx, cz - 1] }, { n: [0, -1], d: CELL - fz, open: solid(cx, cz + 1), cell: [cx, cz + 1] });
    if (!faces.some((f) => f.open && f.d <= reach)) return null;
  }
  const face = faces.filter((f) => f.open).sort((a, b) => a.d - b.d)[0];
  if (!face) return null;
  const [nx, nz] = face.n;
  const [wx, wz] = face.cell;
  // the face plane of the wall cell, 1 cm out
  const px = nx !== 0 ? (wx + 0.5) * CELL + nx * (CELL / 2 + 0.01) : Math.min((wx + 1) * CELL - 0.2, Math.max(wx * CELL + 0.2, x));
  const pz = nz !== 0 ? (wz + 0.5) * CELL + nz * (CELL / 2 + 0.01) : Math.min((wz + 1) * CELL - 0.2, Math.max(wz * CELL + 0.2, z));
  // the decal plane faces +Y; tip it onto the wall so its normal is (nx, 0, nz)
  const rotation: [number, number, number] = nx !== 0 ? [0, 0, -nx * Math.PI / 2] : [nz * Math.PI / 2, 0, 0];
  return { position: [px, y, pz], rotation, normal: [nx, 0, nz] };
}

/** Bullet-hole ring: the slot the next hole takes and the holes past their 20 s (by spawn time, seconds). */
export function nextHoleSlot(spawnedAt: readonly number[]): number {
  let best = 0;
  for (let i = 1; i < spawnedAt.length; i++) if (spawnedAt[i]! < spawnedAt[best]!) best = i;
  return best;
}
export const holeExpired = (spawnedAt: number, now: number): boolean => now - spawnedAt >= BZ_BULLET_HOLE_SECONDS;

// ---- texture patterns (RGBA 0..255), used by scripts/make-decals.ts --------------------------------------------------

function vnoise(x: number, y: number, seed: number): number {
  const xi = Math.floor(x), yi = Math.floor(y), fx = x - xi, fy = y - yi;
  const s = (t: number) => t * t * (3 - 2 * t);
  const a = hash01(xi, yi, seed), b = hash01(xi + 1, yi, seed), c = hash01(xi, yi + 1, seed), d = hash01(xi + 1, yi + 1, seed);
  return a + (b - a) * s(fx) + (c - a) * s(fy) + (a - b - c + d) * s(fx) * s(fy);
}
const fbm = (x: number, y: number, seed: number) => (vnoise(x, y, seed) * 0.55 + vnoise(x * 2.1, y * 2.1, seed + 1) * 0.3 + vnoise(x * 4.3, y * 4.3, seed + 2) * 0.15);

export function decalPixel(kind: DecalKind, u: number, v: number): [number, number, number, number] {
  const dx = u - 0.5, dy = v - 0.5, r = Math.hypot(dx, dy) * 2;
  if (kind === "scorch") {
    const n = fbm(u * 6, v * 6, 17);
    const edge = 1 - Math.min(1, Math.max(0, (r - 0.35 - n * 0.45) / 0.25));
    const a = Math.round(255 * edge * (0.55 + n * 0.45));
    const k = Math.round(14 + n * 22);
    return [k + 6, k + 3, k, a];
  }
  if (kind === "crack") {
    // three jagged branches from the centre, each a thin dark line with a soft halo
    let a = 0;
    for (let b = 0; b < 3; b++) {
      const ang = b * 2.1 + 0.4, ca = Math.cos(ang), sa = Math.sin(ang);
      const along = dx * ca + dy * sa, across = -dx * sa + dy * ca;
      if (along < 0 || along > 0.48) continue;
      const wobble = (fbm(along * 14, b * 3.7, 29) - 0.5) * 0.09;
      const d = Math.abs(across - wobble);
      const width = 0.012 * (1 - along / 0.5) + 0.003;
      a = Math.max(a, d < width ? 1 : Math.max(0, 1 - (d - width) / 0.02) * 0.35);
    }
    return [22, 21, 19, Math.round(255 * a * Math.max(0, 1 - Math.max(0, r - 0.85) / 0.15))];
  }
  // bullet hole: dark core, chipped light ring, soot falloff
  const n = fbm(u * 10, v * 10, 41);
  if (r < 0.16 + n * 0.04) return [8, 8, 8, 250];
  if (r < 0.3 + n * 0.08) return [150, 146, 136, 200];
  const soot = Math.max(0, 1 - (r - 0.3) / 0.6) * (0.4 + n * 0.5);
  return [24, 22, 20, Math.round(255 * Math.min(1, soot))];
}
